package observability

const consoleHTML = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="dark">
<title>RepoArk Console</title>
<style>
:root{--bg:#0a0d12;--panel:#11161e;--panel2:#151b24;--line:#26303d;--text:#eef3f8;--muted:#8d99a8;--ok:#58d68d;--warn:#f4bf4f;--bad:#ff6b6b;--accent:#8b7cff;--accent2:#5ac8fa;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color-scheme:dark;background:var(--bg);color:var(--text)}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% -10%,#19213a 0,transparent 34%),var(--bg);min-height:100vh}.shell{max-width:1480px;margin:auto;padding:20px}.top{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:18px}.brand{display:flex;align-items:center;gap:12px}.mark{width:38px;height:38px;border-radius:12px;background:linear-gradient(135deg,var(--accent),var(--accent2));box-shadow:0 0 34px #6f73ff44}.title{font-size:20px;font-weight:800;letter-spacing:.01em}.subtitle,.muted{color:var(--muted)}.subtitle{font-size:13px;margin-top:2px}.nav{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.nav a,.ghost{color:var(--text);text-decoration:none;border:1px solid var(--line);background:#111722;border-radius:10px;padding:8px 11px;font:inherit;font-size:13px;cursor:pointer}.nav a:hover,.ghost:hover{border-color:#46556b}.layout{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(320px,.7fr);gap:14px}.stack{display:grid;gap:14px}.panel{background:linear-gradient(180deg,#121821,#0f141b);border:1px solid var(--line);border-radius:16px;padding:16px;box-shadow:0 12px 30px #00000022}.panel h2{font-size:14px;letter-spacing:.03em;text-transform:uppercase;color:#b8c2cf;margin:0 0 12px}.kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.kpi{background:var(--panel2);border:1px solid var(--line);border-radius:13px;padding:14px;min-height:96px}.kpi .label{font-size:12px;color:var(--muted)}.kpi .value{font-size:25px;font-weight:800;margin-top:8px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.kpi .note{font-size:11px;color:var(--muted);margin-top:4px}.ok{color:var(--ok)}.warn{color:var(--warn)}.bad{color:var(--bad)}.actions{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.action{display:flex;flex-direction:column;min-height:130px;padding:14px;border-radius:13px;border:1px solid var(--line);background:var(--panel2)}.action .name{font-weight:750}.action .desc{color:var(--muted);font-size:12px;line-height:1.45;margin:7px 0 12px;flex:1}.action button{border:1px solid #3b4655;background:#202836;color:var(--text);border-radius:9px;padding:9px 11px;font:inherit;font-weight:700;cursor:pointer}.action button:hover:not(:disabled){border-color:#71819a}.action button:disabled{opacity:.38;cursor:not-allowed}.action[data-risk="danger"]{border-color:#5d363b}.action[data-risk="danger"] button{background:#3b2025;border-color:#704047}.action[data-risk="elevated"]{border-color:#564b31}.badge{display:inline-flex;align-items:center;gap:6px;font-size:11px;border-radius:999px;border:1px solid var(--line);padding:4px 8px;color:var(--muted)}.dot{width:7px;height:7px;border-radius:99px;background:var(--muted)}.dot.ok{background:var(--ok)}.dot.bad{background:var(--bad)}.jobhead{display:flex;justify-content:space-between;align-items:center;gap:10px}.jobstate{font-size:18px;font-weight:800}.log{margin-top:12px;background:#080b10;border:1px solid #202936;border-radius:12px;height:330px;overflow:auto;padding:12px;font:12px/1.55 ui-monospace,SFMono-Regular,Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere}.logline{display:grid;grid-template-columns:72px minmax(0,1fr);gap:8px}.logtime{color:#647285}.cancel{border:1px solid #6a3f45;background:#351f23;color:#ffd5d8;border-radius:9px;padding:8px 10px;font:inherit;font-size:12px;font-weight:700;cursor:pointer}.cancel:disabled{opacity:.35;cursor:not-allowed}.system{display:grid;grid-template-columns:1fr 1fr;gap:8px}.sys{border:1px solid var(--line);border-radius:10px;padding:10px;background:#101620;font-size:12px}.sys strong{display:block;font-size:13px;margin-bottom:3px}.policyline{font-size:13px;line-height:1.5}.policyitem{padding:8px 0;border-top:1px solid var(--line)}.fleettable{width:100%;border-collapse:collapse;font-size:12px}.fleettable th,.fleettable td{text-align:left;padding:9px 7px;border-bottom:1px solid var(--line)}.fleettable th{color:var(--muted);font-weight:650}.banner{display:none;margin-bottom:14px;padding:11px 13px;border:1px solid #60444a;background:#2b1d21;border-radius:12px;color:#ffd6da;font-size:13px}.footer{color:#647285;font-size:11px;margin:16px 2px 4px}.session{font-size:12px;color:var(--muted);text-align:right}.session a{color:#c9c3ff}.mono{font-family:ui-monospace,SFMono-Regular,Consolas,monospace}.empty{color:var(--muted);font-size:13px;padding:10px 0}
@media(max-width:1080px){.layout{grid-template-columns:1fr}.kpis{grid-template-columns:repeat(2,1fr)}.actions{grid-template-columns:repeat(2,1fr)}}
@media(max-width:680px){.shell{padding:12px}.top{align-items:flex-start;flex-direction:column}.nav{width:100%}.nav a,.ghost{flex:1;text-align:center}.kpis,.actions{grid-template-columns:1fr}.system{grid-template-columns:1fr}.log{height:280px}.kpi{min-height:82px}.kpi .value{font-size:22px}.session{text-align:left}}
</style>
</head>
<body>
<div class="shell">
  <div class="top">
    <div class="brand"><div class="mark"></div><div><div class="title">RepoArk Console</div><div class="subtitle">Backup operations · disaster recovery · integrity</div></div></div>
    <div><div class="nav"><a href="/healthz" target="_blank">Health</a><a href="/metrics" target="_blank">Metrics</a><a id="recoveryLink" href="/restore" style="display:none">Recovery</a><button class="ghost" onclick="refreshAll()">Refresh</button></div><div id="session" class="session"></div></div>
  </div>
  <div id="banner" class="banner"></div>
  <div class="layout">
    <main class="stack">
      <section class="panel"><h2>Overview</h2><div id="kpis" class="kpis"></div></section>
      <section class="panel"><h2>Operations</h2><div id="actions" class="actions"></div></section>
      <section class="panel"><div class="jobhead"><h2 style="margin:0">Activity</h2><div><span id="jobBadge" class="badge"><span class="dot"></span> idle</span> <button id="cancel" class="cancel" onclick="cancelJob()" disabled>Cancel</button></div></div><div id="jobTitle" class="jobstate" style="margin-top:10px">No operation running</div><div id="jobMeta" class="muted" style="font-size:12px;margin-top:4px"></div><div id="log" class="log"><div class="empty">Operation logs will appear here.</div></div></section>
      <section class="panel"><h2>Fleet</h2><div id="fleet"></div></section>
    </main>
    <aside class="stack">
      <section class="panel"><h2>Runtime</h2><div id="system" class="system"></div><div id="root" class="muted mono" style="font-size:11px;margin-top:10px;overflow-wrap:anywhere"></div></section>
      <section class="panel"><h2>Policy</h2><div id="policy" class="policyline">Loading…</div></section>
      <section class="panel"><h2>Control plane</h2><div id="control" class="system"></div></section>
    </aside>
  </div>
  <div class="footer">Web console is local-only unless OIDC is configured. CLI commands remain available for automation and break-glass recovery.</div>
</div>
<script>
let consoleState=null, sessionState=null, currentJob=null, jobEvents=null, jobFallbackTimer=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const age=d=>{if(!d)return'—';const n=Math.max(0,(Date.now()-new Date(d).getTime())/1000);if(n<120)return Math.round(n)+'s';if(n<7200)return Math.round(n/60)+'m';if(n<172800)return Math.round(n/3600)+'h';return Math.round(n/86400)+'d'};
const bytes=n=>{n=Number(n||0);const u=['B','KiB','MiB','GiB','TiB'];let i=0;while(n>=1024&&i<u.length-1){n/=1024;i++}return(i?n.toFixed(1):Math.round(n))+' '+u[i]};
async function req(url,opt={}){const r=await fetch(url,{cache:'no-store',...opt});let body=null;try{body=await r.json()}catch(_){body={error:await r.text()}}return{ok:r.ok,status:r.status,body}}
function banner(msg){const e=document.querySelector('#banner');if(!msg){e.style.display='none';e.textContent='';return}e.textContent=msg;e.style.display='block'}
function roleCanOperate(){if(!sessionState||!sessionState.authenticated)return false;if(sessionState.local)return true;return sessionState.role==='operator'||sessionState.role==='admin'}
function renderSession(){const e=document.querySelector('#session');if(!sessionState||!sessionState.authenticated){e.innerHTML='Remote console · <a href="/auth/login">Sign in</a>';return}if(sessionState.local){e.textContent='Local console · loopback protected';return}e.innerHTML=esc(sessionState.email||'signed in')+' · '+esc(sessionState.role)+(sessionState.role==='admin'?' · <a href="/auth/step-up">step-up</a>':'')}
function renderActions(){const root=document.querySelector('#actions');const actions=(consoleState&&consoleState.actions)||[];const busy=currentJob&&currentJob.state==='running';const allowed=roleCanOperate();root.innerHTML=actions.map(a=>'<div class="action" data-risk="'+esc(a.risk)+'"><div class="name">'+esc(a.label)+'</div><div class="desc">'+esc(a.description)+'</div><button '+((!a.enabled||busy||!allowed)?'disabled':'')+' onclick="startJob(\''+esc(a.name)+'\',\''+esc(a.risk)+'\')">'+(a.enabled?'Run':'Disabled')+'</button></div>').join('')||'<div class="empty">No operations available.</div>'}
function renderSystem(){if(!consoleState)return;const t=consoleState.tools||{},g=consoleState.github_auth||{};const items=[['GitHub auth',!!g.ready],['git',!!t.git],['git-lfs',!!t.git_lfs],['Docker',!!t.docker],['restic',!!t.restic],['rclone',!!t.rclone]];document.querySelector('#system').innerHTML=items.map(x=>'<div class="sys"><strong>'+esc(x[0])+'</strong><span class="'+(x[1]?'ok':'bad')+'">'+(x[1]?'ready':'missing')+'</span></div>').join('');document.querySelector('#root').textContent='Backup root: '+(consoleState.backup_root||'—');document.querySelector('#recoveryLink').style.display=(consoleState.features&&consoleState.features.recovery_ui)?'inline-block':'none'}
function renderJob(){const badge=document.querySelector('#jobBadge'),cancel=document.querySelector('#cancel'),title=document.querySelector('#jobTitle'),meta=document.querySelector('#jobMeta'),log=document.querySelector('#log');if(!currentJob){badge.innerHTML='<span class="dot"></span> idle';title.textContent='No operation running';meta.textContent='';cancel.disabled=true;log.innerHTML='<div class="empty">Operation logs will appear here.</div>';renderActions();return}const running=currentJob.state==='running',cls=currentJob.state==='succeeded'?'ok':currentJob.state==='failed'?'bad':currentJob.state==='cancelled'?'warn':'';badge.innerHTML='<span class="dot '+(running?'ok':cls)+'"></span> '+esc(currentJob.state);title.textContent=currentJob.name;meta.textContent='Started '+age(currentJob.started_at)+' ago'+(currentJob.error?' · '+currentJob.error:'');cancel.disabled=!running||!roleCanOperate();const nearBottom=log.scrollHeight-log.scrollTop-log.clientHeight<40;log.innerHTML=(currentJob.logs||[]).map(x=>'<div class="logline"><span class="logtime">'+esc(new Date(x.at).toLocaleTimeString())+'</span><span>'+esc(x.message)+'</span></div>').join('')||'<div class="empty">Waiting for output…</div>';if(nearBottom)log.scrollTop=log.scrollHeight;renderActions()}
async function loadSession(){const x=await req('/api/v1/console/session');sessionState=x.body||{authenticated:false};renderSession()}
async function loadState(){const x=await req('/api/v1/console/state');if(x.ok){consoleState=x.body;renderSystem();renderActions()}}
async function loadJob(){const x=await req('/api/v1/console/job');if(x.ok){currentJob=x.body.job;renderJob()}}
function startJobFallback(){if(!jobFallbackTimer)jobFallbackTimer=setInterval(loadJob,3000)}
function connectJobEvents(){if(!window.EventSource){startJobFallback();return}if(jobEvents)jobEvents.close();const es=new EventSource('/api/v1/console/events');jobEvents=es;es.addEventListener('job',ev=>{try{const body=JSON.parse(ev.data),wasRunning=currentJob&&currentJob.state==='running';currentJob=body.job;renderJob();if(wasRunning&&currentJob&&currentJob.state!=='running')loadOverview()}catch(_){}});es.onopen=()=>{if(jobFallbackTimer){clearInterval(jobFallbackTimer);jobFallbackTimer=null}};es.onerror=()=>{startJobFallback()}}
async function loadOverview(){const [s,f,p,c]=await Promise.all([req('/api/v1/status'),req('/api/v1/fleet'),req('/api/v1/policy'),req('/api/v1/control/stats')]);const m=(s.body&&s.body.manifest)||{};const good=!!(s.body&&s.body.ok);const total=(m.repositories||[]).length;document.querySelector('#kpis').innerHTML='<div class="kpi"><div class="label">Overall</div><div class="value '+(good?'ok':'bad')+'">'+(good?'HEALTHY':'DEGRADED')+'</div><div class="note">manifest + policy</div></div><div class="kpi"><div class="label">Repositories</div><div class="value">'+Number(m.succeeded||0)+'/'+total+'</div><div class="note">'+Number(m.failed||0)+' failed</div></div><div class="kpi"><div class="label">Last backup</div><div class="value">'+age(m.ended_at)+'</div><div class="note">'+Number(m.warning_count||0)+' warnings</div></div><div class="kpi"><div class="label">CAS reclaimed</div><div class="value">'+bytes(m.cas&&m.cas.reclaimed_bytes)+'</div><div class="note">content-addressed storage</div></div>';const pr=p.body||{};document.querySelector('#policy').innerHTML=pr.healthy?'<span class="ok">All policy gates pass.</span>':((pr.violations||[]).length?(pr.violations||[]).map(v=>'<div class="policyitem"><span class="bad">'+esc(v.code||'violation')+'</span><br>'+esc(v.message||'')+'</div>').join(''):'<span class="muted">Policy state unavailable.</span>');const rows=(f.body&&f.body.accounts)||[];document.querySelector('#fleet').innerHTML=rows.length?'<table class="fleettable"><thead><tr><th>Account</th><th>State</th><th>Repos</th><th>Age</th></tr></thead><tbody>'+rows.map(a=>'<tr><td>'+esc(a.name)+'</td><td class="'+(a.ok?'ok':'bad')+'">'+(a.ok?'OK':'FAIL')+'</td><td>'+Number(a.succeeded||0)+'/'+(Number(a.succeeded||0)+Number(a.failed||0))+'</td><td>'+age(a.ended_at)+'</td></tr>').join('')+'</tbody></table>':'<div class="empty">Fleet mode is disabled.</div>';const cs=c.body||{};if(cs.enabled){const x=cs.stats||{};document.querySelector('#control').innerHTML=[['Queued',x.queued_jobs||0],['Running',x.running_jobs||0],['Agents',x.connected_agents||0],['Stranded',x.stranded_jobs||0],['Replicas',x.ready_replicas||0],['Approvals',x.pending_approvals||0]].map(v=>'<div class="sys"><strong>'+esc(v[0])+'</strong>'+esc(v[1])+'</div>').join('')}else document.querySelector('#control').innerHTML='<div class="empty">Control plane disabled.</div>';if(!s.ok&&s.body&&s.body.error)banner(s.body.error);else banner('')}
async function startJob(name,risk){if(risk==='danger'&&!confirm('This is a privileged operation that can change GitLab state. Continue?'))return;if(risk==='elevated'&&!confirm('Run '+name+' now?'))return;const headers={};if(sessionState&&sessionState.csrf)headers['X-CSRF-Token']=sessionState.csrf;const x=await req('/api/v1/console/jobs/'+encodeURIComponent(name),{method:'POST',headers});if(!x.ok){banner(x.body&&x.body.error?x.body.error:'Unable to start operation');if(x.status===403&&risk==='danger')banner((x.body&&x.body.error?x.body.error:'Authorization failed')+' — use step-up sign in.');return}banner('');currentJob=x.body.job;renderJob();loadOverview()}
async function cancelJob(){const headers={};if(sessionState&&sessionState.csrf)headers['X-CSRF-Token']=sessionState.csrf;const x=await req('/api/v1/console/job/cancel',{method:'POST',headers});if(!x.ok)banner(x.body&&x.body.error?x.body.error:'Unable to cancel operation');if(jobFallbackTimer)await loadJob()}
async function refreshAll(){await Promise.all([loadSession(),loadState(),loadJob(),loadOverview()])}
refreshAll();connectJobEvents();setInterval(loadOverview,15000);setInterval(loadSession,60000);
</script>
</body>
</html>`
